import re

def harden_ssh_config(config_path: str) -> dict:
    """Granskar sshd_config och returnerar rekommendationer."""
    rekommenderat = {
        "PermitRootLogin": "no",
        "PasswordAuthentication": "no",
        "PermitEmptyPasswords": "no",
        "X11Forwarding": "no",
        "Protocol": "2",
        "MaxAuthTries": "3",
        "ClientAliveInterval": "300",
        "ClientAliveCountMax": "2",
    }

    rekommendationer = {}
    aktiva = {}

    try:
        with open(config_path, "r", encoding="utf-8") as f:
            for rad in f:
                rad = rad.strip()
                if not rad or rad.startswith("#"):
                    continue
                delar = re.split(r"\s+", rad, maxsplit=1)
                if len(delar) == 2:
                    aktiva[delar[0]] = delar[1]
    except FileNotFoundError:
        return {"fel": f"Kunde inte läsa {config_path}"}

    for nyckel, varde in rekommenderat.items():
        nuvarande = aktiva.get(nyckel)
        if nuvarande is None:
            rekommendationer[nyckel] = f"Saknas – sätt '{nyckel} {varde}'"
        elif nuvarande.lower() != varde.lower():
            rekommendationer[nyckel] = f"'{nuvarande}' → rekommenderat: '{varde}'"

    if not rekommendationer:
        rekommendationer["status"] = "Konfigurationen följer rekommenderade inställningar."

    return rekommendationer
